/*⁣‌⁠‌‍‌‌​‌‍‌‌‌‌⁠‍⁠⁠⁠​⁠​‌⁠⁠​⁠⁠‍‍‌​‌⁠​​​‌‍⁠‌‌‍‍‍‌‌‍⁠⁠‌​‌‍⁠‍​⁠‌​⁠‌⁠⁠​⁣ ================= 基础重置 ================= */
.mz-story-dashboard-widget {
  display: flex; 
  width: 100%; height: 100%; position: relative;
  font-family: -apple-system, BlinkMacSystemFont, "Apple SD Gothic Neo", "Segoe UI", sans-serif;
  background-color: transparent !important; 
  box-sizing: border-box; overflow: hidden;
  border-radius: clamp(16px, 4vw, 24px);
}
img { object-fit: cover; width: 100%; height: 100%; display: block; }

/* ================= 底层背景 ================= */
.widget-bg {
  position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  z-index: 1; background-color: transparent; 
  border-radius: clamp(16px, 4vw, 24px);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.03); 
  overflow: hidden; 
}
.widget-bg img { width: 100%; height: 100%; object-fit: cover; }

/* ================= 内部排版主容器 ================= */
.card-content {
  flex: 1; width: 100%; height: 100%;
  background-color: transparent !important; 
  display: flex; flex-direction: column; 
  padding: clamp(12px, 3.5vw, 20px);
  box-sizing: border-box; 
  position: relative; z-index: 2;
}

/* ================= 顶部：名片区 ================= */
.header-zone {
  display: flex; justify-content: space-between; align-items: center;
  margin-bottom: clamp(10px, 2.5vw, 14px);
}
.profile-group {
  display: flex; align-items: center; gap: clamp(8px, 2vw, 12px);
  min-width: 0; 
}
.avatar-box {
  width: clamp(36px, 9vw, 44px); height: clamp(36px, 9vw, 44px);
  border-radius: 50%; overflow: hidden; flex-shrink: 0;
  border: 1px solid rgba(0,0,0,0.05); background: #f5f5f5;
}
.user-info { display: flex; flex-direction: column; min-width: 0; }
.username {
  font-size: clamp(14px, 3.5vw, 16px); font-weight: 700;
  color: var(--text-main); letter-spacing: 0.2px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.bio {
  font-size: clamp(10px, 2.5vw, 12px); font-weight: 400;
  color: var(--text-sub); margin-top: 2px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}

/* 🌟 右上角日期胶囊 (已加入幽灵半透机制) */
.date-badge {
  font-size: clamp(10px, 2.5vw, 12px); font-weight: 600;
  color: var(--text-sub); flex-shrink: 0;
  padding: 4px 10px;
  border-radius: 12px; border: 1px solid var(--divider-color);

  position: relative; 
  z-index: 1; 
  overflow: hidden; /* 防止底层背景溢出圆角 */
}
.date-badge::before {
  content: ""; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background: var(--pill-bg); 
  opacity: 0.55; /* 无论填什么色，强制变为 55% 透明度 */
  z-index: -1; /* 垫在文字下方 */
}

/* ================= 中部：虚线分割 ================= */
.dashed-divider {
  width: 100%; height: 0;
  border-bottom: 1.5px dashed var(--divider-color);
  margin-bottom: clamp(10px, 2.5vw, 14px);
}

/* ================= 底部：画廊与状态胶囊 ================= */
.gallery-zone {
  flex: 1; 
  display: flex; gap: clamp(6px, 1.5vw, 12px);
  min-height: 0; 
}
.pic-box {
  flex: 1; 
  border-radius: clamp(8px, 2vw, 12px); overflow: hidden;
  background-color: rgba(250,250,250,0.5);
  border: 1px solid rgba(0,0,0,0.04);
}

.footer-zone {
  display: flex; justify-content: center;
  margin-top: clamp(8px, 2vw, 12px);
  width: 100%;
}

/* 🌟 底部状态胶囊 (已加入幽灵半透机制) */
.status-pill {
  display: inline-flex; width: fit-content; max-width: 100%; 
  align-items: center; gap: 6px;
  border: 1px solid var(--divider-color);
  padding: clamp(4px, 1vw, 6px) clamp(12px, 3vw, 16px);
  border-radius: 20px; 

  position: relative; 
  z-index: 1; 
  overflow: hidden; /* 防止底层背景溢出圆角 */
}
.status-pill::before {
  content: ""; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background: var(--pill-bg); 
  opacity: 0.55; /* 无论填什么色，强制变为 55% 透明度 */
  z-index: -1; /* 垫在文字下方 */
}

.pill-icon {
  font-size: clamp(10px, 2.5vw, 12px); color: var(--text-main);
  flex-shrink: 0;
}
.pill-text {
  font-size: clamp(10px, 2.5vw, 12px); font-weight: 500;
  color: var(--text-sub);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}

body { margin: 0; padding: 16px; box-sizing: border-box; font-family: -apple-system, sans-serif; background: #fff; height: 100%; }
.widget { display: flex; height: 100%; gap: 16px; }
.left-panel { flex: 0 0 70px; display: flex; flex-direction: column; justify-content: space-between; }
.icon-wrap { width: 36px; height: 36px; background: #007aff; border-radius: 50%; display: flex; justify-content: center; align-items: center; }
.bottom-info { display: flex; flex-direction: column; }
.count { font-size: 34px; font-weight: 600; color: #000; line-height: 1; margin-bottom: 2px; }
.title { font-size: 15px; font-weight: 600; color: #007aff; display: flex; align-items: center; }
.right-panel { flex: 1; display: flex; flex-direction: column; justify-content: flex-start; margin-top: -7px; overflow-y: auto; }
.item { display: flex; align-items: center; padding: 7px 0; transition: all 0.4s ease; }
.item.hide { opacity: 0; transform: translateX(15px); }
.circle { width: 22px; height: 22px; border-radius: 50%; border: 1.5px solid #ccc; margin-right: 12px; box-sizing: border-box; cursor: pointer; flex-shrink: 0; }
.item.done .circle { background: #007aff; border-color: #007aff; position: relative; }
.item.done .circle::after { content: ''; position: absolute; left: 6px; top: 3px; width: 4px; height: 9px; border: solid white; border-width: 0 2px 2px 0; transform: rotate(45deg); }
.item.done .text { color: #888; }
.text { font-size: 13px; color: #333; flex: 1; outline: none; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.divider { height: 1px; border-bottom: 1px dashed #e5e5e5; margin-left: 34px; transition: 0.4s; }

/* 外层容器：适配2×1矮宽尺寸，极致压缩纵向空间，横向适配宽屏 */
.my-custom-box {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  background: transparent;
  /* 上下内边距极致压缩，适配2×1的矮高度，左右内边距适配宽尺寸 */
  padding: 4px 14px;
  box-sizing: border-box;
  /* 头像和文字的间距，适配更宽的横向空间 */
  gap: 12px;
  border-radius: 20px;
  overflow: hidden;
}

/* 头像：适配2×1的矮高度，尺寸控制在纵向不溢出，保证清晰 */
.avatar {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  object-fit: cover;
  flex-shrink: 0;
}

/* 文字容器：压缩行间距，极致适配纵向矮高度 */
.text-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  /* 两行文字间距极致压缩，适配2×1的矮高度 */
  gap: 4px;
  flex: 1;
}

/* 主标题：适配宽尺寸，字号协调，纵向不溢出 */
.main-title {
  font-size: 15px;
  font-weight: 600;
  font-family: Georgia, 'Times New Roman', Times, serif;
  color: #ffffff;
  /* 行高1，极致压缩纵向占用空间 */
  line-height: 1;
}

/* 电池行：压缩间距，适配矮高度 */
.battery-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

/* 电池图标：等比例压缩高度，适配2×1的矮尺寸 */
.battery {
  position: relative;
  width: 22px;
  height: 11px;
  border: 1.5px solid #ffffff;
  border-radius: 2px;
  flex-shrink: 0;
}
/* 电池正极：同步缩小，适配矮尺寸 */
.battery::after {
  content: '';
  position: absolute;
  right: -3px;
  top: 50%;
  transform: translateY(-50%);
  width: 2px;
  height: 5px;
  background: #ffffff;
  border-radius: 1px;
}
/* 电池填充 */
.battery-fill {
  width: 90%;
  height: 100%;
  background: #ffffff;
  border-radius: 1px;
}

/* 百分比数字：适配矮高度，字号协调 */
.percent {
  font-size: 13px;
  font-weight: 600;
  color: #ffffff;
  line-height: 1;
}

body { margin: 0; padding: 0; background: transparent; height: 100%; box-sizing: border-box; font-family: -apple-system, sans-serif; }
.glass {
  position: relative;
  overflow: hidden;
  width: 100%; height: 100%;
  border-radius: 22px;
  background: radial-gradient(circle at 30% 30%, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0) 60%, rgba(255,255,255,0.05) 100%);
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
  box-shadow: inset 2px 2px 6px rgba(255,255,255,0.9), inset -2px -2px 6px rgba(0,0,0,0.05), 0 8px 20px rgba(0,0,0,0.1);
  border: 1px solid rgba(255,255,255,0.5);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  color: #fff; text-shadow: 0 2px 6px rgba(0,0,0,0.3); gap: 4px;
}
.temp, .loc, .hl, .status { position: relative; z-index: 1; }
.loc { font-size: 13px; display: flex; align-items: center; gap: 4px; font-weight: 500; margin-right: 7px;}
.temp { font-size: 42px; font-weight: 700; margin: -5px 0; text-shadow: 0 4px 12px rgba(0,0,0,0.4); margin-left: 11px;}
.hl { display: flex; gap: 16px; align-items: center; margin: 4px 0; }
.hl-block { display: flex; align-items: center; gap: 4px; }
.hl-text { display: flex; flex-direction: column; font-size: 10px; line-height: 1.1; opacity: 0.8; }
.hl-num { font-size: 24px; font-weight: 400; }
.status { font-size: 11px; font-weight: 500; display: flex; align-items: center; gap: 4px; cursor: pointer; padding: 4px 8px; border-radius: 10px; background: rgba(255,255,255,0.1); transition: 0.2s; margin-top: -1px;}
.status:active { transform: scale(0.95); background: rgba(255,255,255,0.2); }
#effect { position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none; z-index: 0; }

.my-custom-box {
  width: 100%;
  height: 100%;
  background: #f3f3f3;
  border-radius: 8vw;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  font-family: -apple-system, BlinkMacSystemFont, sans-serif;
  box-sizing: border-box;
}

/*⁣‌⁠‌‍‌‌​‌‍‌‌‌‌⁠‍⁠⁠⁠​⁠​‌⁠⁠​⁠⁠‍‍‌​‌⁠​​​‌‍⁠‌‌‍‍‍‌‌‍⁠⁠‌​‌‍⁠‍​⁠‌​⁠‌⁠⁠​⁣ 顶栏 */
.top-nav {
  width: 100%;
  background: #ffffff;
  padding: 2.5vw 4vw;
  box-sizing: border-box;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-shrink: 0;
}

.nav-left,
.nav-right {
  display: flex;
  align-items: center;
}

.nav-right {
  gap: 3vw;
}

.mini-icon {
  font-size: 4.8vw;
  color: #9a9a9a;
  line-height: 1;
}

.nav-icon {
  width: 5vw;
  height: 5vw;
  object-fit: contain;
}

.nav-avatar {
  width: 6vw;
  height: 6vw;
  border-radius: 50%;
  object-fit: cover;
}

/* 主体区域 */
.main-content {
  flex: 1;
  padding: 3vw 3.5vw 3vw;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  overflow: hidden;
}

/* 用户信息 */
.user-info {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex-shrink: 0;
}

.main-avatar {
  width: 16vw;
  height: 16vw;
  border-radius: 50%;
  object-fit: cover;
}

.username {
  margin: 1.5vw 0 0;
  font-size: 4.2vw;
  font-weight: 600;
  color: #333;
}

.user-link {
  margin-top: 0.5vw;
  font-size: 2.6vw;
  color: #777;
}

/* 数据栏 */
.stats {
  width: 70%;
  margin: 3vw auto 0;
  display: flex;
  justify-content: space-between;
  flex-shrink: 0;
}

.stat-item {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.stat-number {
  font-size: 3.4vw;
  font-weight: 600;
  color: #4b8ddd;
}

.stat-label {
  margin-top: 0.3vw;
  font-size: 2.5vw;
  color: #777;
}

/* 大白卡 */
.content-card {
  margin-top: 3vw;
  background: #ffffff;
  border-radius: 5vw;
  overflow: hidden;
  flex: 1;
  min-height: 0;
}

/* 每一部分 */
.card-section {
  position: relative;
  padding: 3.5vw 4vw;
}

/* 分割线 */
.card-divider {
  width: 100%;
  height: 1px;
  background: rgba(0,0,0,0.05);
}

/* 标题 */
.card-title {
  margin: 0 0 1.5vw;
  font-size: 2.8vw;
  font-weight: 600;
  color: #4d8ddb;
}

/* 内容 */
.card-text {
  margin: 0 0 1vw;
  font-size: 2.9vw;
  color: #444;
  line-height: 1.35;
}

/* 三点 */
.card-more {
  position: absolute;
  top: 3vw;
  right: 4vw;
  font-size: 2.8vw;
  color: #aaa;
}

.mz-music-widget {
  width: 100%; height: 100%; position: relative;
  font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "PingFang SC", sans-serif;
  box-sizing: border-box; overflow: hidden;
  border-radius: 36px; 
  background-color: transparent; 
}

.glass-bg {
  position: absolute; top: 0; left: 0; 
  width: 100%; height: 100%; z-index: 1;
  backdrop-filter: blur(25px) saturate(180%);
  -webkit-backdrop-filter: blur(25px) saturate(180%);
  box-shadow: 
    inset 0 1px 0px var(--highlight-top), 
    inset 1px 1px 0px rgba(255, 255, 255, 0.04), 
    inset -1px 1px 0px rgba(255, 255, 255, 0.04),
    inset 1px 0px 0px rgba(255, 255, 255, 0.02),
    inset -1px 0px 0px rgba(255, 255, 255, 0.02),
    inset 0 -1px 0px var(--highlight-bottom);
}

.content-layer {
  position: relative; z-index: 3;
  display: flex; flex-direction: column; 
  height: 100%;
  padding: 12px 14px 12px 14px; 
  box-sizing: border-box;
}

/*⁣‌⁠‌‍‌‌​‌‍‌‌‌‌⁠‍⁠⁠⁠​⁠​‌⁠⁠​⁠⁠‍‍‌​‌⁠​​​‌‍⁠‌‌‍‍‍‌‌‍⁠⁠‌​‌‍⁠‍​⁠‌​⁠‌⁠⁠​⁣ --- 1. 顶部栏 --- */
.top-row {
  display: flex; justify-content: space-between; align-items: flex-start;
}
.album-cover {
  width: 72px; height: 72px; 
  border-radius: 22px; 
  overflow: hidden;
  background-color: transparent;
  box-shadow: 0 6px 14px rgba(0,0,0,0.04); 
  margin-left: 6px; 
}
.album-cover img {
  width: 100%; height: 100%; object-fit: cover; display: block;
}

.cover-placeholder {
  width: 100%; height: 100%; 
  position: relative;
  display: none; align-items: center; justify-content: center;
  color: var(--icon-color);
  z-index: 1;
}
.cover-placeholder::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background-color: var(--placeholder-bg-color);
  backdrop-filter: blur(20px) brightness(1.1) saturate(120%);
  -webkit-backdrop-filter: blur(20px) brightness(1.1) saturate(120%);
  z-index: -1;
}
.cover-placeholder svg { 
  width: 32px; height: 32px; 
  opacity: 0.9;
}

.cast-btn {
  width: 46px; height: 46px;
  display: flex; align-items: center; justify-content: center;
  color: var(--cast-icon-color);
  margin-top: 4px; 
  position: relative;
  z-index: 1;
}
.cast-btn::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  border-radius: 50%;
  background-color: var(--cast-bg-color);
  backdrop-filter: blur(25px) brightness(1.06) saturate(120%);
  -webkit-backdrop-filter: blur(25px) brightness(1.06) saturate(120%);
  box-shadow: 
    inset 0 1px 0px rgba(255, 255, 255, 0.2),
    inset 0 0 0 1px rgba(255, 255, 255, 0.08);
  z-index: -1;
}
.cast-btn svg { 
  width: 26px; height: 26px; 
}

/* 🌟 === 中等/小尺寸适配 === 🌟 */
.mz-music-widget.size-medium .album-cover { width: 67px; height: 67px; border-radius: 20px; }
.mz-music-widget.size-medium .cover-placeholder svg { width: 30px; height: 30px; }
.mz-music-widget.size-medium .cast-btn { width: 42px; height: 42px; }
.mz-music-widget.size-medium .cast-btn svg { width: 24px; height: 24px; }

.mz-music-widget.size-small .album-cover { width: 62px; height: 62px; border-radius: 18px; }
.mz-music-widget.size-small .cover-placeholder svg { width: 28px; height: 28px; }
.mz-music-widget.size-small .cast-btn { width: 38px; height: 38px; }
.mz-music-widget.size-small .cast-btn svg { width: 22px; height: 22px; }

/* --- 2. 文本信息区 --- */
.text-row {
  display: flex; flex-direction: column; 
  gap: 0px; 
  margin-top: auto; 
  margin-bottom: 12px; 
  align-items: flex-start; 
  margin-left: 6px; 
}
.song-title {
  color: var(--song-color); font-size: var(--song-size); 
  font-weight: 500; 
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  max-width: 100%; 
  line-height: 1.15; 
}
.artist-name {
  color: var(--artist-color); font-size: var(--artist-size); 
  font-weight: 400;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  max-width: 100%;
  line-height: 1.15;
}

/* --- 3. 底部播放控制区 --- */
.controls-row {
  display: flex; justify-content: center; align-items: center; 
  gap: 8px; 
  margin-bottom: -4px; 
}
.ctrl-icon {
  color: var(--icon-color);
  display: flex; align-items: center; justify-content: center;
}

/* 🌟 去除了 prev-next 的独立透明度和混合模式，彻底与 play-btn 保持一致纯色 */

.play-btn svg { width: 36px; height: 30px; }
.prev-next svg { width: 52px; height: 30px; }

/*⁣‌⁠‌‍‌‌​‌‍‌‌‌‌⁠‍⁠⁠⁠​⁠​‌⁠⁠​⁠⁠‍‍‌​‌⁠​​​‌‍⁠‌‌‍‍‍‌‌‍⁠⁠‌​‌‍⁠‍​⁠‌​⁠‌⁠⁠​⁣ ================= 全局容器 ================= */
.mz-tape-widget {
  width: 100%;
  height: 100%;
  position: relative;
  border-radius: 20px;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", Helvetica, Arial, sans-serif;
  --accent-color: #6f8396; 
  --text2-color: #555555; 
}

.bg-layer {
  position: absolute;
  inset: 0;
  z-index: 1;
}

/* ================= 核心排版 ================= */
.content-layer {
  position: relative;
  z-index: 2;
  width: 100%;
  height: 100%;
  display: flex;
  box-sizing: border-box;
  /* 🌟 使用百分比内边距：无论手机屏幕多大，周围留白的视觉比例永远一致 */
  padding: 5% 6%; 
  gap: 5%; 
}

.polaroid-zone {
  flex: 1.3;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6%; /* 相对间距，防止小手机上太拥挤 */
  min-width: 0; /* 核心自适应：防止内部图片撑爆容器 */
}

.polaroid {
  width: 48%; 
  background: #ffffff;
  /* 🌟 使用百分比构建拍立得，经典底部留白随设备自适应 */
  padding: 2% 2% 12% 2%; 
  border-radius: 2px;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.06), 0 1px 4px rgba(0, 0, 0, 0.03);
  position: relative;
}

.img-wrap {
  width: 100%;
  aspect-ratio: 1 / 1; 
  background: #f4f4f4;
  overflow: hidden;
}

.img-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.tape {
  position: absolute;
  top: -8px; 
  left: 50%;
  width: 32px;
  height: 12px;
  background: rgba(220, 220, 220, 0.85); 
  box-shadow: 0 1px 2px rgba(0,0,0,0.05);
}

.tape-1 { transform: translateX(-50%) rotate(-3deg); }
.tape-2 { transform: translateX(-50%) rotate(2deg); }

.handwriting {
  position: absolute;
  bottom: 4%; /* 手写字也改用百分比定位 */
  left: 10px;
  font-family: "Brush Script MT", "Snell Roundhand", "Times New Roman", cursive, serif;
  font-style: italic;
  font-size: 14px;
  color: #666666;
}

.p-left { transform: rotate(-2deg) translateY(4px); }
.p-right { transform: rotate(1.5deg) translateY(-6px); }

/* --- 右侧：清透文案区 --- */
.text-zone {
  flex: 0.85; /* 给文案多一点呼吸空间 */
  display: flex;
  flex-direction: column;
  /* 🌟 往下调整：增加 top padding 到 18px，整体文案块下移 */
  padding: 18px 0 12px 0; 
  min-width: 0;
}

.title-text {
  font-size: 15px;
  font-weight: 500;
  color: var(--accent-color); 
  letter-spacing: 0.5px;
  line-height: 1; 
  /* 🌟 进一步往下微调：增加 margin-top，与倾斜的左图完美对齐 */
  margin-top: 6px; 

  /* 防小屏溢出：如果手机特别窄，文案会自动加省略号而不破坏排版 */
  white-space: nowrap; 
  overflow: hidden;
  text-overflow: ellipsis;
}

.desc-wrapper {
  margin: auto 0; 
  display: flex;
  flex-direction: column;
  gap: 6px; /* 稍微缩紧间距，让居中效果在各种机型上都紧凑好看 */
}

.desc-text {
  font-size: 12px;
  font-weight: 400;
  color: var(--text2-color); 
  line-height: 1.4; 
  display: -webkit-box;
  -webkit-line-clamp: 2; 
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.text-bottom {
  display: flex;
  justify-content: flex-start; 
}

.heart-icon {
  font-size: 18px;
  color: var(--accent-color); 
  line-height: 1;
}

.mz-glass-clock {
  width: 100%; height: 100%; position: relative;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "SF Pro", "Helvetica Neue", sans-serif;
  box-sizing: border-box;
}

.glass-layer {
  position: absolute; left: -5%; right: -5%; 
  background-size: contain; background-position: center; background-repeat: no-repeat;
  -webkit-mask-size: contain; -webkit-mask-position: center; -webkit-mask-repeat: no-repeat;

  backdrop-filter: blur(28px) saturate(160%);
  -webkit-backdrop-filter: blur(28px) saturate(160%);
  z-index: 2;
}

#dateGlass {
  top: 18%; 
  height: 14%; 
}

#timeGlass {
  top: 22%; 
  bottom: 0%; 
}

/* =========================================
   🌟 双路毛玻璃共用类（提亮到 1.06）
========================================= */
.glass-layer {
  position: absolute; left: -5%; right: -5%; 
  background-size: contain; background-position: center; background-repeat: no-repeat;
  -webkit-mask-size: contain; -webkit-mask-position: center; -webkit-mask-repeat: no-repeat;

  /* 🌟 核心提亮：在滤镜最后加上 brightness(1.06) */
  backdrop-filter: blur(28px) saturate(160%) brightness(1.2);
  -webkit-backdrop-filter: blur(28px) saturate(160%) brightness(1.2);

  /* 备用提亮方案：如果底层壁纸太暗，也可以再加一层整体提亮滤镜 */
  filter: brightness(1.2); 

  z-index: 2;
}

/* 基础重置，居中显示 */
body {
