    transparent 0px,
    black calc(env(safe-area-inset-top, 20px) + 35px),
    black calc(100% - 90px),
    transparent calc(100% - 1px)
  ) !important;
  mask-image: linear-gradient(
    to bottom,
    transparent 0px,
    black calc(env(safe-area-inset-top, 20px) + 35px),
    black calc(100% - 90px),
    transparent calc(100% - 1px)
