/* =========================================================
   【终极校色：气泡同色无色差 + 彻底封杀深色聚焦态与自带动画】
   ========================================================= */

/* 1. 无论是发送键，还是打字预选时变蓝的 AI 键，严格取气泡同款变量色 */
.send-btn-custom,
button.send-btn-custom,
.input-row-wrapper .send-btn-custom,
.input-row-wrapper:has(.input-box-custom:not(:placeholder-shown)) .input-btn-ai {
  /* 彻底关闭位移与渐变动画 */
  transform: scale(1) translateY(0px) !important;
  transition: none !important;
  animation: none !important;

  /* 严格与当前模式下的气泡颜色（--bubble-me-bg）1:1 绝对一致 */
  background: var(--bubble-me-bg) !important;
  background-color: var(--bubble-me-bg) !important;
  background-image: none !important;
  border: none !important;
  opacity: 1 !important;
  visibility: visible !important;
  z-index: 10 !important;

