  --btn-sticker-translate-x: 0px; 
  --btn-ai-opacity: 0;
  --btn-ai-translate-x: 0px; 

  /* ---- 💸 转账卡片颜色配置 ---- */
  --transfer-bg-top: var(--bubble-me-bg);    
  --transfer-bg-bottom: var(--bubble-them-bg); 
  --transfer-text-top: var(--bubble-me-text);  
  --transfer-text-bottom: var(--bubble-them-text); 
  --transfer-icon-border: var(--bubble-me-text); 
  --transfer-icon-fill: var(--bubble-me-text); 

  /* ---- 🎤 iOS 语音样式配置 ---- */
  --voice-waveform-height: 22px !important;
