padding-top: env(safe-area-inset-top, 20px) !important; / 自动适配刘海/灵动岛 */
border-bottom: 1px solid #e5e5ea !important;
}
/* 2. 强行解除绝对定位和遮罩魔法，让“完成”和“返回”按钮乖乖回到原位并绝对可点！ /
.chat-detail-screen .chat-header-custom:not(:has(.header-profile-section)) [class="btn"],
.chat-detail-screen .glass-header:not(:has(.header-profile-section)) [class*="btn"] {
position: relative !important;
width: auto !important;
height: auto !important;
margin: 0 !important;
background: transparent !important;
background-color: transparent !important;
background-image: none !important;
-webkit-mask-image: none !important;
mask-image: none !important;
transform: none !important;
opacity: 1 !important;
right: auto !important;
left: auto !important;
pointer-events: auto !important;
z-index: 10 !important;
}
