/* ========================================================
   🩹 终极暴力补丁：坐标钉死法，强制分离通话与记录键！
   ======================================================== */
/* 1. 废除系统排版，赋予它们独立的点击面积和最高层级 */
.chat-detail-screen .header-btn-video,
.chat-detail-screen .header-btn-phone {
  opacity: 0 !important; 
  pointer-events: auto !important; 
  position: absolute !important; /* 👈 强制绝对定位，彻底脱离系统束缚 */
  width: 44px !important;        /* 👈 保证有足够的点击面积 */
  height: 44px !important;
  margin: 0 !important;
  padding: 0 !important;
  transform: none !important;    /* 👈 废除上次失败的平移 */
  z-index: 9999 !important;
  margin-top: var(--config-header-icon-top-right) !important;
}

/* 2. 🎥 通话记录键：死死钉在最右侧可见图标的左边 */
.chat-detail-screen .header-btn-video {
  right: 50px !important; 
}

/* 3. 📞 语音通话键：死死钉在通话记录键的更左边 */
.chat-detail-screen .header-btn-phone {
  right: 100px !important; 
}

/* ========================================================
🩹 终极隔离补丁 V2：暴力解除设定页的高度限制与遮罩！
======================================================== /
/ 1. 彻底废除 145px 高度和 45px 顶距，强制设定页顶栏恢复苗条身材！ /
.chat-detail-screen .chat-header-custom:not(:has(.header-profile-section)),
.chat-detail-screen .glass-header:not(:has(.header-profile-section)) {
background: #f8f8f8 !important; / 恢复设定页的原生浅灰白底 /
height: auto !important;
min-height: 44px !important;
max-height: 100px !important;
padding-top: env(safe-area-inset-top, 20px) !important; / 自动适配刘海/灵动岛 */
border-bottom: 1px solid #e5e5ea !important;
}
/* 2. 强行解除绝对定位和遮罩魔法，让“完成”和“返回”按钮乖乖回到原位并绝对可点！ /
.chat-detail-screen .chat-header-custom:not(:has(.header-profile-section)) [class="btn"],
.chat-detail-screen .glass-header:not(:has(.header-profile-section)) [class*="btn"] {
position: relative !important;
width: auto !important;
height: auto !important;
margin: 0 !important;
background: transparent !important;
background-color: transparent !important;
background-image: none !important;
-webkit-mask-image: none !important;
mask-image: none !important;
transform: none !important;
opacity: 1 !important;
right: auto !important;
left: auto !important;
pointer-events: auto !important;
z-index: 10 !important;
}
/* 3. 释放被强制隐藏的原生返回箭头等 SVG 图标 */
.chat-detail-screen .chat-header-custom:not(:has(.header-profile-section)) svg,
.chat-detail-screen .glass-header:not(:has(.header-profile-section)) svg {
display: block !important;
}

