  }
}
@media (prefers-color-scheme: dark) {
  /* 最底部 / 安全区露出的白底 */
  html:root:root,
  html:root:root body,
  html:root:root #chat-detail-screen,
  html:root:root body .chat-detail-screen {
    background-color: #0f0f10 !important;
  }

  /* 输入区上沿的分隔线 + 输入区整圈(含底部留白) */
  html:root:root body .input-area-custom {
    border-top: 1px solid #0f0f10 !important;
    border-color: #0f0f10 !important;
    box-shadow: none !important;
    outline: none !important;
  }
}

:root {
  /*⁣‌⁠‌‍‌‌​‌‍‌‌‌‌⁠‍⁠⁠⁠​⁠​‌⁠⁠​⁠⁠‍‍‌​‌⁠​​​‌‍⁠‌‌‍‍‍‌‌‍⁠⁠‌​‌‍⁠‍​⁠‌​⁠‌⁠⁠​⁣ ==========================================================================
     🌟 小白快捷参数配置区 (所有常用微调集中在此，修改数值即生效) 🌟
     ========================================================================== */

  /* ------------ 1. 消息间距与屏幕边缘距离控制 ------------ */
  --group-gap: 20px;                      /* 换人发言时的消息间距 */
  --same-sender-gap: 3px;                 /* 同一个人连续发多条消息的气泡间距 */

  --bubble-edge-me: 46px;                 /* 我方气泡距右侧边缘 (已往边缘靠拢) */
  --bubble-edge-them: 46px;               /* 对方气泡距左侧边缘 (已往边缘靠拢) */

  /* ------------ 2. ------------ */
  --avatar-them-display: none;            

  /* ------------ 3. 挂件位置与大小 (侧上方提拉) ------------ */
  --deco-them-size: 50px;                 /* 对方挂件大小 */
  --deco-them-x: -48px;                   /* 对方挂件左右位置 */
  --deco-them-y: -28px;                   /* 对方挂件上下位置 (向上提拉) */

  --deco-me-size: 50px;                   /* 我方挂件大小 */
  --deco-me-x: -48px;                     /* 我方挂件左右位置 */
  --deco-me-y: -28px;                     /* 我方挂件上下位置 (向上提拉) */

  /* ------------ 4. 纯CSS绘制：顶部小缺角与单字防脱离 ------------ */
  --bubble-border-weight: 1.5px;          /* 气泡框线的粗细 */
  --bubble-border-color: #1a1a1a;         /* 气泡框线的颜色 */
  --bubble-radius: 18px;                  /* 气泡圆角 */

  --bubble-horn-top: -6px;                /* 小缺角冲出顶部的距离 */
  --bubble-horn-side: 14px;               /* 小缺角停靠位置 */
  --bubble-horn-size: 13px;               /* 小缺角的大小 */
  --bubble-min-width: 52px;               /* 气泡最小宽度：彻底防止单字/符号导致缺角滑落脱节 */

  --bubble-padding-top: 6px;              /* 气泡上方内边距 */
  --bubble-padding-bottom: 6px;           /* 气泡下方内边距 */
  --bubble-padding-x: 12px;               /* 气泡左右内边距 */

  --bubble-me-bg: #ffe8ee;                /* 我方气泡底色：纯白 */
  --bubble-me-color: #1a1a1a;             /* 我方文字颜色 */

  --bubble-them-bg: #E8F5FE;              /* 对方气泡底色：纯白 */
  --bubble-them-color: #1a1a1a;           /* 对方文字颜色 */

  /* ------------ 5. 引用气泡内部底色与图标微调 ------------ */
  --reply-bg-me: #ffffff;                 /* 我方引用的气泡底色 */
  --reply-bg-them: #ffffff;               /* 对方引用的气泡底色 */

  --reply-icon-me: url('https://imgbed.heliar.top/i/7Op_RSxw6vvBNfF2_IMG_1112.jpeg');
  --reply-icon-them: url('https://imgbed.heliar.top/i/2sD0Ek_ADV8mJ3GZ_IMG_1112.jpeg');

  --reply-icon-size: 24px;                /* 被引用小图标尺寸 */
  --reply-icon-y: 0px;                    
  --reply-text-y: -1px;                   

  /* ------------ 6. 思维链专属向下调节参数 ------------ */
  --thinking-margin-top: 10px;            
  --thinking-margin-bottom: -16px;        

  /* ------------ 7. 顶栏 (Header) 整体高度与昵称调整 ------------ */
  --header-height: 120px;                 
  --header-title-size: 19px;              
  --header-title-x: 0px;                  
  --header-title-y: 2px;                  

  /* ------------ 8. 顶栏各按键图标 (缩放与位置微调) ------------ */
  --header-btn-gap: 9px;                  
  --btn-back-scale: 0.8;                  
  --btn-back-x: 0px;                      
  --btn-back-y: 0px;                      
  --btn-phone-scale: 0.96;                
  --btn-phone-x: 0px;                     
  --btn-phone-y: 6px;                     
  --btn-video-scale: 0.96;                
  --btn-video-x: 0px;                     
  --btn-video-y: 0px;                     
  --btn-info-scale: 0.96;                 
  --btn-info-x: 0px;                      
  --btn-info-y: 6px;                      

  /* ------------ 9. 低栏 (Footer) 整体高度与边距调节 ------------ */
  --footer-height: 56px;                  
  --footer-padding-top: 10px;             
  --footer-padding-bottom: 26px;          

  /* ------------ 10. 素材 URL ------------ */
  --deco-them-url: url('https://imgbed.heliar.top/i/H7t6GWbcsvdXN9_7_IMG_1109.webp');
  --deco-me-url: url('https://imgbed.heliar.top/i/GBUDfLMgqBKGfX5c_IMG_1063.webp');

  --back-btn-icon: url('https://imgbed.heliar.top/i/h5FQ-4_uEZv9G0DK_IMG_0950.webp');
  --info-btn-icon: url('https://imgbed.heliar.top/i/CrlVQ-t3jQRC6Z_9_IMG_0949.webp');
  --phone-btn-icon: url('https://imgbed.heliar.top/i/_SCFGxphBiTS-Wim_IMG_0948.webp');
  --video-btn-icon: none;

  --plus-btn-icon: url('https://imgbed.heliar.top/i/7D9JSQNOsILMYoPd_IMG_0960.webp');
  --sticker-btn-icon: url('https://imgbed.heliar.top/i/ths3gK_gph-BBGiU_IMG_0956.webp');
  --mic-btn-icon: none;
  --ai-btn-icon: url('https://imgbed.heliar.top/i/f6r-WHyWtbai_rFC_IMG_0957.webp');
  --send-btn-icon: url('https://imgbed.heliar.top/i/f6r-WHyWtbai_rFC_IMG_0957.webp');

  --transfer-bg-url: url('https://imgbed.heliar.top/i/zh6k06j-YwsjennV_IMG_0996.webp');  
  --transfer-icon-url: url('https://imgbed.heliar.top/i/h8JGS4t3sTPcMyYo_IMG_1079.webp'); 

  /* ==========================================================================
     ⚙️ 核心系统底层变量 (锁定约18字自动换行)
     ========================================================================== */
  --chat-header-bg: transparent; 
  --chat-header-blur: 0px;
  --chat-header-border: transparent;

  --input-area-bg: #ffffff;
  --input-area-blur: 0px;
  --input-area-border-top: 1px solid #f0f0f0;

  --chat-message-max-width: 70%;          /* 限制宽度为70%，约18字强制折行 */
  --plain-content-max-width: 70%;
  --chat-messages-padding: 12px 0px;

  --image-msg-max-width: 220px;
  --image-me-max-width: 220px;
  --image-them-max-width: 220px;

  --sticker-msg-max-width: 98px;
  --sticker-msg-max-height: 98px;
  --sticker-me-max-width: 98px;
  --sticker-them-max-width: 98px;

  --voice-waveform-height: 20px;
  --voice-waveform-gap: 2.5px;
  --voice-bar-min-width: 2px;
  --voice-bar-max-width: 3.5px;
  --voice-bar-radius: 999px;
  --voice-play-btn-size: 24px;

  --transfer-card-bg: transparent;
  --transfer-card-border: none;
  --transfer-card-shadow: none;
  --transfer-success-card-bg: transparent;
  --transfer-success-card-border: none;
  --transfer-rejected-card-bg: transparent;
  --transfer-rejected-card-border: none;
  --transfer-expired-card-bg: transparent;
  --transfer-expired-card-border: none;
}

/* ================= 顶栏深度布局 ================= */

.chat-header-custom {
  height: var(--header-height) !important;
  min-height: var(--header-height) !important;
}

.header-avatar-container,
.chat-header-avatar,
.chat-header-subtitle {
  display: none !important;
}

.header-profile-section {
  position: absolute !important;
  left: 50% !important;
  top: 70% !important;
  transform: translate(calc(-50% + var(--header-title-x)), calc(-50% + var(--header-title-y))) !important;
  margin: 0 !important;
  padding: 0 !important;
  width: max-content !important;
  pointer-events: none !important;
  z-index: 5 !important;
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
}

.chat-header-title {
  text-align: center !important;
  font-size: var(--header-title-size) !important;
  font-weight: 700 !important;
  color: #1a1a1a !important;
  margin: 0 !important;
  white-space: nowrap !important;
}

.header-btn-back {
  transform: scale(var(--btn-back-scale)) translate(var(--btn-back-x), var(--btn-back-y)) !important;
}

.header-btn-video {
  order: 1 !important;
  opacity: 0 !important;
  width: 32px !important;
  height: 32px !important;
  min-width: 32px !important;
  min-height: 32px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  cursor: pointer !important;
  pointer-events: auto !important;
  background: transparent !important;
  border: none !important;
  z-index: 10 !important;
  margin-right: var(--header-btn-gap) !important;
  transform: scale(var(--btn-video-scale)) translate(var(--btn-video-x), var(--btn-video-y)) !important;
}

.header-btn-phone {
  order: 2 !important;
  margin-right: var(--header-btn-gap) !important;
  cursor: pointer !important;
  pointer-events: auto !important;
  transform: scale(var(--btn-phone-scale)) translate(var(--btn-phone-x), var(--btn-phone-y)) !important;
}

.header-btn-info {
  order: 3 !important;
  cursor: pointer !important;
  pointer-events: auto !important;
  transform: scale(var(--btn-info-scale)) translate(var(--btn-info-x), var(--btn-info-y)) !important;
}

/* ================= 低栏深度布局 ================= */

.input-area-custom {
  min-height: var(--footer-height) !important;
  padding: var(--footer-padding-top) 14px var(--footer-padding-bottom) 14px !important;
  box-sizing: border-box !important;
}

.input-row-wrapper {
  display: flex !important;
  align-items: center !important;
}

.input-btn-plus {
  transform: scale(1.20) translateY(1.0px) !important;
  margin-top: 0 !important;
  align-self: center !important;
}

.input-action-bar-custom {
  background: #f2f2f4 !important;
  border-radius: 999px !important;
  border: none !important;
  min-height: 38px !important;
  height: 38px !important;
  padding: 0 7.5px 0 14px !important;
  display: flex !important;
  align-items: center !important;
  position: relative !important;
  overflow: visible !important;
  margin-right: 44px !important;
  box-sizing: border-box !important;
}

.input-box-custom {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  font-size: 15px !important;
  color: #262626 !important;
  flex: 1 !important;
  height: 100% !important;
  line-height: 38px !important;
  resize: none !important;
}

.input-btns-right {
  display: flex !important;
  align-items: center !important;
  position: static !important;
  margin: 0 !important;
  padding: 0 !important;
  gap: 2px !important;
  overflow: visible !important;
}

.input-btn-mic {
  order: 1 !important;
  opacity: 0 !important;
  cursor: pointer !important;
  pointer-events: auto !important;
  width: 26px !important;
  height: 26px !important;
  margin: 0 !important;
}

.input-btn-sticker {
  order: 2 !important;
  position: relative !important;
  transform: translateX(0.5px) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  margin: 0 !important;
  z-index: 2 !important;
}

.input-btn-ai {
  position: absolute !important;
  left: calc(100% + 10px) !important;
  top: 50% !important;
  transform: translateY(-50%) scale(1.23) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  margin: 0 !important;
}

.input-btns-right:has(.send-btn-custom) .input-btn-ai {
  opacity: 0 !important;
  pointer-events: none !important;
}

.send-btn-custom {
  position: absolute !important;
  left: calc(100% + 10px) !important;
  top: 50% !important;
  transform: translateY(-50%) scale(1.23) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  margin: 0 !important;
  background-color: transparent !important;
  background-image: url('https://imgbed.heliar.top/i/f6r-WHyWtbai_rFC_IMG_0957.webp') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  width: 26px !important;
  height: 26px !important;
  z-index: 10 !important;
  cursor: pointer !important;
}

.send-btn-custom svg {
  display: none !important;
}

/* ================= 消息外层行容器与边缘距离控制 ================= */

.msg-bubble-wrapper {
  margin-bottom: var(--same-sender-gap, 3px) !important;
}

.msg-bubble-wrapper.is-first {
  margin-top: var(--group-gap, 8px) !important;
}

.msg-bubble-wrapper.msg-me {
  padding-right: var(--bubble-edge-me, 46px) !important;
  padding-left: 0 !important;
}

.msg-bubble-wrapper.msg-them {
  padding-left: var(--bubble-edge-them, 46px) !important;
  padding-right: 0 !important;
}

.msg-avatar-them-container,
.msg-avatar-container,
.msg-avatar-me-container {
  display: none !important;
}

/* ================= 纯 CSS 绘制气泡本体与无缝犄角 ================= */

.bubble-deco-me,
.bubble-deco-them {
  overflow: visible !important;
}

.msg-content-stack {
  max-width: var(--chat-message-max-width, 70%) !important;
  width: auto !important;
}

/* 我方气泡 */
.bubble-me-custom,
.msg-plain-me {
  background-color: var(--bubble-me-bg) !important;
  color: var(--bubble-me-color) !important;
  border-radius: var(--bubble-radius) !important;
  border: var(--bubble-border-weight) solid var(--bubble-border-color) !important;
  padding: var(--bubble-padding-top) var(--bubble-padding-x) var(--bubble-padding-bottom) var(--bubble-padding-x) !important;
  line-height: 1.4 !important;
  box-shadow: none !important;
  position: relative !important;
  overflow: visible !important;
  margin-top: 0px !important;
  margin-right: 0px !important;
  max-width: 100% !important;
  min-width: var(--bubble-min-width, 52px) !important; /* 单字防缩塌陷 */
  display: inline-block !important;
  word-break: break-word !important;
  overflow-wrap: break-word !important;
  box-sizing: border-box !important;
}

/* 对方气泡 */
.bubble-them-custom,
.msg-plain-them {
  background-color: var(--bubble-them-bg) !important;
  color: var(--bubble-them-color) !important;
  border-radius: var(--bubble-radius) !important;
  border: var(--bubble-border-weight) solid var(--bubble-border-color) !important;
  padding: var(--bubble-padding-top) var(--bubble-padding-x) var(--bubble-padding-bottom) var(--bubble-padding-x) !important;
  line-height: 1.4 !important;
  box-shadow: none !important;
  position: relative !important;
  overflow: visible !important;
  margin-top: 0px !important;
  margin-left: 0px !important;
  max-width: 100% !important;
  min-width: var(--bubble-min-width, 52px) !important; /* 单字防缩塌陷 */
  display: inline-block !important;
  word-break: break-word !important;
  overflow-wrap: break-word !important;
  box-sizing: border-box !important;
}

/* 我方缺角 (定位在气泡顶部的右侧) */
.bubble-me-custom.first::before,
.msg-plain-me.plain-first::before,
.bubble-me-custom.single::before,
.msg-plain-me.plain-single::before,
[data-first="true"] .bubble-me-custom::before {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  top: var(--bubble-horn-top, -6px) !important;         
  right: var(--bubble-horn-side, 14px) !important;      
  width: var(--bubble-horn-size, 13px) !important;
  height: var(--bubble-horn-size, 13px) !important;
  background-color: var(--bubble-me-bg) !important;
  border-top: var(--bubble-border-weight) solid var(--bubble-border-color) !important; 
  border-right: var(--bubble-border-weight) solid var(--bubble-border-color) !important;
  border-bottom: none !important;
  border-left: none !important;
  border-top-right-radius: 4px !important; 
  transform: rotate(-25deg) !important;           
  z-index: 2 !important;                          
}

/* 对方缺角 (定位在气泡顶部的左侧) */
.bubble-them-custom.first::before,
.msg-plain-them.plain-first::before,
.bubble-them-custom.single::before,
.msg-plain-them.plain-single::before,
[data-first="true"] .bubble-them-custom::before {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  top: var(--bubble-horn-top, -6px) !important;         
  left: var(--bubble-horn-side, 14px) !important;       
  width: var(--bubble-horn-size, 13px) !important;
  height: var(--bubble-horn-size, 13px) !important;
  background-color: var(--bubble-them-bg) !important;
  border-top: var(--bubble-border-weight) solid var(--bubble-border-color) !important;
  border-left: var(--bubble-border-weight) solid var(--bubble-border-color) !important;
  border-bottom: none !important;
  border-right: none !important;
  border-top-left-radius: 4px !important;  
  transform: rotate(25deg) !important;            
  z-index: 2 !important;                          
}

/* ================= 彻底剥除：所有非文本卡片外层边框与背景 ================= */

.bubble-me-custom:has(img),
.bubble-them-custom:has(img),
.bubble-me-custom:has(.msg-image-wrapper),
.bubble-them-custom:has(.msg-image-wrapper),
