.chat-detail-screen .msg-bubble-wrapper:has([class*="select"]) .msg-avatar-them-container,
.chat-detail-screen .msg-bubble-wrapper:has(input[type="checkbox"]) .msg-avatar-them-ghost,
.chat-detail-screen .msg-bubble-wrapper:has(input[type="checkbox"]) .msg-avatar-them-container {
