  color: #ffffff !important;
  font-weight: bold !important;
  text-shadow: 
    1px  1px 0 #000,
   -1px -1px 0 #000,
    1px -1px 0 #000,
   -1px  1px 0 #000,
    1px  0px 0 #000,
   -1px  0px 0 #000,
    0px  1px 0 #000,
    0px -1px 0 #000 !important;
