  margin-bottom: 4px !important;
  margin-left: 4px !important;
  width: fit-content !important;
  pointer-events: auto !important;
}

/* 隐藏原生折叠三角与💭图标 */
.chat-detail-screen .nuo-thinking-arrow,
.chat-detail-screen .nuo-thinking-icon {
  display: none !important;
}

/* 原生文字字号归零，避免布局撑开，但保留事件通道 */
.chat-detail-screen .nuo-thinking-label {
  font-size: 0 !important;
  line-height: 0 !important;
  opacity: 0 !important;
}

/* 剥离灰底胶囊并设置标准移动端触控热区，保证一触即发展开 */
.chat-detail-screen .nuo-thinking-btn {
  display: inline-flex !important;
