/* ═══════════════════════════════════════════════════════════
   💰 【转账卡片金额下方动态切换补丁】直接替换末尾补丁
   ═══════════════════════════════════════════════════════════ */

/* 🌟 1. 平时未领取状态：确保金额下方的“转账给xx”正常显示，绝不隐藏 */
div.chat-detail-screen .msg-transfer-card [class*="subtitle"],
div.chat-detail-screen .msg-transfer-card .msg-transfer-subtitle {
  display: block !important;
  visibility: visible !important;
  opacity: 0.92 !important;
  position: absolute !important;
  top: 33px !important;
  left: 60px !important;
  width: 150px !important;
  min-height: 16px !important;
  height: 16px !important;
  font-size: 12px !important;
  font-weight: 500 !important;
  line-height: 16px !important;
  color: var(--transfer-text-top, #ffffff) !important;
  -webkit-text-fill-color: var(--transfer-text-top, #ffffff) !important;
  z-index: 6 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  text-align: left !important;
  transform: none !important;
}

/* 🌟 2. 当已接收转账时：隐藏原字，防塌陷并动态替换为“已接收” */
div.chat-detail-screen .msg-transfer-card.msg-transfer-success [class*="subtitle"],
div.chat-detail-screen .msg-transfer-card:has(.success) [class*="subtitle"],
div.chat-detail-screen .msg-transfer-card:has([class*="success"]) [class*="subtitle"],
div.chat-detail-screen .msg-transfer-card[class*="success"] [class*="subtitle"] {
  font-size: 0 !important;
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  overflow: visible !important; /* 关键：解决高度塌陷裁切问题 */
}

div.chat-detail-screen .msg-transfer-card.msg-transfer-success [class*="subtitle"]::after,
div.chat-detail-screen .msg-transfer-card:has(.success) [class*="subtitle"]::after,
div.chat-detail-screen .msg-transfer-card:has([class*="success"]) [class*="subtitle"]::after,
div.chat-detail-screen .msg-transfer-card[class*="success"] [class*="subtitle"]::after {
  content: "已接收" !important;
  font-size: 12px !important;
  font-weight: 500 !important;
  visibility: visible !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  color: var(--transfer-text-top, #ffffff) !important;
  -webkit-text-fill-color: var(--transfer-text-top, #ffffff) !important;
  line-height: 16px !important;
  white-space: nowrap !important;
}

/* 🌟 3. 当已退还转账时：隐藏原字，防塌陷并动态替换为“已退还” */
div.chat-detail-screen .msg-transfer-card.msg-transfer-rejected [class*="subtitle"],
div.chat-detail-screen .msg-transfer-card:has(.rejected) [class*="subtitle"],
div.chat-detail-screen .msg-transfer-card:has([class*="rejected"]) [class*="subtitle"],
div.chat-detail-screen .msg-transfer-card[class*="rejected"] [class*="subtitle"] {
  font-size: 0 !important;
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  overflow: visible !important; /* 关键：解决高度塌陷裁切问题 */
}

div.chat-detail-screen .msg-transfer-card.msg-transfer-rejected [class*="subtitle"]::after,
div.chat-detail-screen .msg-transfer-card:has(.rejected) [class*="subtitle"]::after,
