}

/* =========================================================
   ✨ 终极修复：表情包匹配（显示不全 & 点不动）补丁
   ========================================================= */

/* 1. 修复“只显示一个半”与“点不动”：
   精准选中输入框上方的表情/联想容器，解除之前 [class*="sticker"] 造成的 105px 误伤，
   恢复 100% 宽度，并赋予最高级的触控权限 */
.chat-detail-screen .input-area-custom > div:not(.input-row-wrapper):not(.more-options-popup),
.chat-detail-screen .input-area > div:not(.input-row-wrapper):not(.more-options-popup),
.chat-detail-screen [class*="suggestion"],
.chat-detail-screen [class*="match"],
.chat-detail-screen [class*="keyword"] {
    max-width: 100% !important;
    max-height: none !important;
    width: auto !important;
    height: auto !important;
    pointer-events: auto !important; 
    z-index: 99999 !important;
    position: relative !important;
}

/* 2. 彻底打通内部所有层级的触控，确保手指点击有效 */
.chat-detail-screen .input-area-custom > div:not(.input-row-wrapper):not(.more-options-popup) *,
.chat-detail-screen .input-area > div:not(.input-row-wrapper):not(.more-options-popup) *,
.chat-detail-screen [class*="suggestion"] *,
.chat-detail-screen [class*="match"] *,
.chat-detail-screen [class*="keyword"] * {
    pointer-events: auto !important;
    cursor: pointer !important;
    max-width: none !important; /* 解除内部各级 div 被误伤缩小的限制 */
}

/* 3. 保证匹配出来的单个表情图片尺寸正常，绝不被挤扁 */
.chat-detail-screen .input-area-custom > div:not(.input-row-wrapper):not(.more-options-popup) img,
.chat-detail-screen [class*="suggestion"] img,
.chat-detail-screen [class*="match"] img,
.chat-detail-screen [class*="keyword"] img {
