    max-height: 75px !important;
    width: auto !important;
    height: auto !important;
    flex-shrink: 0 !important;   /* 核心：防止横向排布时图片被挤压变形 */
    pointer-events: auto !important;
}

/* =========================================================
   🚀 顶栏与底栏高度独立调节补丁 (请直接粘贴在代码最末尾)
   ========================================================= */

/* 
   ⚠️ 以后调整顶栏和底栏的高低，直接在这里改数值即可！
   （因为放在代码最末尾，这里的数值会强行覆盖掉前面的所有设置）
*/

/* =========================================================
   🟢 1. 顶栏整体调节 (左侧返回键 + 中间大头像与昵称 + 右侧设定键) 
   👉 调整方法：把下面两行代码里的 【0px】 换成一模一样的数值。
      (正数往下沉，例如 5px；负数往上提，例如 -5px)
   ========================================================= */

/* 控制大头像和昵称气泡 */
.chat-detail-screen .header-profile-section {
  top: calc(env(safe-area-inset-top, 44px) + 33px + 0px) !important; /* 👈 改这里的 0px */
}

/* 控制左右两端的气泡 */
.chat-detail-screen .header-btn-back,
.chat-detail-screen .header-btn-info {
  margin-top: calc(-6px + 0px) !important; /* 👈 改这里的 0px (必须和上面填一样的数字) */
}

/* =========================================================
   🔵 2. 低栏高度独立调节 (只动菜单键和输入框，不动阴影)
   👉 调整方法：修改 bottom 冒号后面的 【0px】。
      (正数往上提，例如 10px；负数往下沉，例如 -10px)
   ========================================================= */

/* 控制菜单键 + 输入胶囊所在的外层行容器 */
.chat-detail-screen .input-row-wrapper {
  position: relative !important;

  bottom: 0px !important; /* 👈 改这里的 0px 来调整输入框高低 */

  margin-bottom: 0 !important; /* ⚠️ 这行的 0 不要动 */
  z-index: 10 !important;
}

/* 彻底把底部全背景（暗角渐变阴影）死死钉在屏幕最底下 */
.chat-detail-screen .input-area,
.chat-detail-screen .input-area-custom {
  bottom: 0 !important; 
}

/*⁣‌⁠‌‍‌‌​‌‍‌‌‌‌⁠‍⁠⁠⁠​⁠​‌⁠⁠​⁠⁠‍‍‌​‌⁠​​​‌‍⁠‌‌‍‍‍‌‌‍⁠⁠‌​‌‍⁠‍​⁠‌​⁠‌⁠⁠​⁣ =========================================================
   💬 深黑顶栏 · 微信绿气泡 · 锐利高光质感版
   ========================================================= */
:root {
