/* ── 2. 隐藏默认图标、小三角，修改按钮文字 ── */
.nuo-thinking-icon { display: none !important; }
.nuo-thinking-arrow { display: none !important; } /* 🎯 咔嚓掉小三角 */
.nuo-thinking-label { font-size: 0 !important; }
.nuo-thinking-label::after {
    content: "@하트 비트" !important;
    font-size: 12px !important;
    font-weight: 600 !important;
    color: #8e8e8e !important;
}

/* ── 3. 改造面板基础样式 (Ins 经典白底卡片) ── */
.chat-detail-screen {
  --thinking-panel-bg: #ffffff;
  --thinking-panel-border-full: 1px solid #dbdbdb; /* Ins 标准边框色 */
  --thinking-panel-border-left: none; 
  --thinking-panel-radius: 4px;
  --thinking-panel-shadow: 0 1px 2px rgba(0,0,0,0.02); /* 极弱的阴影，几乎扁平 */

  /* 🎯 顶部留66px给Header，底部留90px给操作栏和点赞时间 */
  --thinking-panel-padding: 66px 16px 90px 16px;

  /* 正文文字样式 (Ins 帖子描述) */
  --thinking-text-color: #262626;
  --thinking-text-font-size: 14px;
  --thinking-text-font-style: normal;
  --thinking-text-line-height: 1.5;
  --thinking-panel-overflow: visible;
}

/* ── 4. 核心魔法：全 SVG 多重背景绘制 Ins 界面 ── */
.nuo-thinking-panel {
    background-image: 
        var(--char-avatar), /* 图层1: 顶部头像 */
        /* 图层2: 顶部右侧“更多”图标 (三个点) */
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23262626' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><circle cx='12' cy='12' r='1.5'/><circle cx='19' cy='12' r='1.5'/><circle cx='5' cy='12' r='1.5'/></svg>"),
        /* 图层3: 顶部横向分割线 */
        linear-gradient(to right, #efefef, #efefef),
        /* 图层4: 底部左侧操作栏 (爱心、评论、纸飞机) */
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='100' height='24' viewBox='0 0 100 24'><style>.icon{fill:none;stroke:%23262626;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;}</style><path class='icon' d='M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z' transform='translate(0,0)'/><path class='icon' d='M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z' transform='translate(38,0)'/><g transform='translate(76,0)'><line class='icon' x1='22' y1='2' x2='11' y2='13'/><polygon class='icon' points='22 2 15 22 11 13 2 9 22 2'/></g></svg>"),
        /* 图层5: 底部右侧“收藏”图标 */
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23262626' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round'><path d='M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z'/></svg>"),
        /* 图层6: 底部文字 (点赞数 + 时间) */
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='200' height='40' viewBox='0 0 200 40'><style>.likes{font-family:system-ui,-apple-system,sans-serif;font-size:13px;font-weight:600;fill:%23262626;}.time{font-family:system-ui,-apple-system,sans-serif;font-size:11px;fill:%238e8e8e;}</style><text x='0' y='14' class='likes'>10,245 次赞</text><text x='0' y='34' class='time'>2 小时前</text></svg>") !important; 

    /* 📐 控制各个图层的大小 */
    background-size: 
        32px 32px, /* 图层1: 头像大小 */
        20px 20px, /* 图层2: 更多图标大小 */
        100% 1px,  /* 图层3: 分割线贯穿全宽 */
        100px 24px, /* 图层4: 左侧操作栏大小 */
        24px 24px, /* 图层5: 收藏图标大小 */
        200px 40px !important; /* 图层6: 底部文字大小 */

    /* 📍 控制各个图层的位置 */
    background-position: 
        16px 12px, /* 图层1: 头像 (左上角) */
        calc(100% - 16px) 18px, /* 图层2: 更多图标 (右上角) */
        0 56px, /* 图层3: 分割线 (头像下方) */
        16px calc(100% - 54px), /* 图层4: 操作栏 (距底54px) */
        calc(100% - 16px) calc(100% - 54px), /* 图层5: 收藏 (距底54px，靠右) */
        16px calc(100% - 8px) !important; /* 图层6: 文字 (最底部) */

    background-repeat: no-repeat !important;
}

/* ── 5. 强制头像变成正圆 (Ins风格) ── */
.nuo-thinking-panel {
    /* 利用伪元素遮罩或者直接在背景图上无法改圆角，但我们可以用一个巧妙的技巧 */
    /* 实际上 var(--char-avatar) 只是图片，圆角由系统控制，这里我们不强求，通常已经是圆的了 */
}

/* ── 6. 绘制顶部 Header 的名字 ── */
.nuo-thinking-panel::before {
    content: var(--char-name) !important;
    position: absolute !important;
    top: 18px !important;
    left: 58px !important;
    font-size: 14px !important;
    font-weight: 600 !important;
    color: #262626 !important;
    z-index: 2 !important;
    display: block !important;
}

/* ── 7. 清空原本的 after ── */
.nuo-thinking-panel::after {
    display: none !important;
}

/* =========================================================
   ⏱️ 聊天界面时间戳美化：灰色胶囊风格
   ========================================================= */

/* ── 1. 消息之间的时间戳 (如：下午 2:30) ── */
.timestamp-custom {
    background-color: rgba(0, 0, 0, 0.06) !important; /* 极浅的灰色背景 */
    color: #8e8e8e !important; /* 经典的次级灰文字 */
    padding: 4px 12px !important; /* 撑开胶囊的内边距 */
    border-radius: 100px !important; /* 完美的胶囊圆角 */
    font-size: 11px !important;
    font-weight: 500 !important;
    width: fit-content !important; /* 宽度紧贴文字 */
    margin: 16px auto 12px auto !important; /* 保证绝对居中，上下留白 */
    backdrop-filter: blur(4px) !important; /* 微微的毛玻璃质感 */
}

/* ── 2. 日期分隔线 (如：今天、昨天) 保持同款胶囊风格 ── */
:root {
    --date-divider-bg: rgba(0, 0, 0, 0.06);
    --date-divider-color: #8e8e8e;
    --date-divider-size: 11px;
    --date-divider-weight: 500;
    --date-divider-padding: 4px 12px;
    --date-divider-radius: 100px;
    --date-divider-margin: 16px 0;
}

data.css:
.my-custom-box {
  width: 100%;
  height: 100%;
  background: #f3f3f3;
  border-radius: 8vw;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  font-family: -apple-system, BlinkMacSystemFont, sans-serif;
  box-sizing: border-box;
}

/*⁣‌⁠‌‍‌‌​‌‍‌‌‌‌⁠‍⁠⁠⁠​⁠​‌⁠⁠​⁠⁠‍‍‌​‌⁠​​​‌‍⁠‌‌‍‍‍‌‌‍⁠⁠‌​‌‍⁠‍​⁠‌​⁠‌⁠⁠​⁣ 顶栏 */
.top-nav {
  width: 100%;
  background: #ffffff;
  padding: 2.5vw 4vw;
  box-sizing: border-box;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-shrink: 0;
}

.nav-left,
.nav-right {
  display: flex;
  align-items: center;
}

.nav-right {
  gap: 3vw;
}

.mini-icon {
  font-size: 4.8vw;
  color: #9a9a9a;
  line-height: 1;
}

.nav-icon {
  width: 5vw;
  height: 5vw;
  object-fit: contain;
}

.nav-avatar {
  width: 6vw;
  height: 6vw;
  border-radius: 50%;
  object-fit: cover;
}

/* 主体区域 */
.main-content {
  flex: 1;
  padding: 3vw 3.5vw 3vw;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  overflow: hidden;
}

/* 用户信息 */
.user-info {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex-shrink: 0;
}

.main-avatar {
  width: 16vw;
  height: 16vw;
  border-radius: 50%;
  object-fit: cover;
}

.username {
  margin: 1.5vw 0 0;
  font-size: 4.2vw;
  font-weight: 600;
  color: #333;
}

.user-link {
  margin-top: 0.5vw;
  font-size: 2.6vw;
  color: #777;
}

/* 数据栏 */
.stats {
  width: 70%;
  margin: 3vw auto 0;
  display: flex;
  justify-content: space-between;
  flex-shrink: 0;
}

.stat-item {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.stat-number {
  font-size: 3.4vw;
  font-weight: 600;
  color: #4b8ddd;
}

.stat-label {
  margin-top: 0.3vw;
  font-size: 2.5vw;
  color: #777;
}

/* 大白卡 */
.content-card {
  margin-top: 3vw;
  background: #ffffff;
  border-radius: 5vw;
  overflow: hidden;
  flex: 1;
  min-height: 0;
}

/* 每一部分 */
.card-section {
  position: relative;
  padding: 3.5vw 4vw;
}

/* 分割线 */
.card-divider {
  width: 100%;
  height: 1px;
  background: rgba(0,0,0,0.05);
}

/* 标题 */
.card-title {
  margin: 0 0 1.5vw;
  font-size: 2.8vw;
  font-weight: 600;
  color: #4d8ddb;
}

/* 内容 */
.card-text {
  margin: 0 0 1vw;
  font-size: 2.9vw;
  color: #444;
  line-height: 1.35;
}

/* 三点 */
.card-more {
  position: absolute;
  top: 3vw;
  right: 4vw;
  font-size: 2.8vw;
  color: #aaa;
}

.mz-music-widget {
  width: 100%; height: 100%; position: relative;
  font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "PingFang SC", sans-serif;
  box-sizing: border-box; overflow: hidden;
  border-radius: 36px; 
  background-color: transparent; 
}

.glass-bg {
  position: absolute; top: 0; left: 0; 
  width: 100%; height: 100%; z-index: 1;
  backdrop-filter: blur(25px) saturate(180%);
  -webkit-backdrop-filter: blur(25px) saturate(180%);
  box-shadow: 
    inset 0 1px 0px var(--highlight-top), 
    inset 1px 1px 0px rgba(255, 255, 255, 0.04), 
    inset -1px 1px 0px rgba(255, 255, 255, 0.04),
    inset 1px 0px 0px rgba(255, 255, 255, 0.02),
    inset -1px 0px 0px rgba(255, 255, 255, 0.02),
    inset 0 -1px 0px var(--highlight-bottom);
}

.content-layer {
  position: relative; z-index: 3;
  display: flex; flex-direction: column; 
  height: 100%;
  padding: 12px 14px 12px 14px; 
  box-sizing: border-box;
}

/*⁣‌⁠‌‍‌‌​‌‍‌‌‌‌⁠‍⁠⁠⁠​⁠​‌⁠⁠​⁠⁠‍‍‌​‌⁠​​​‌‍⁠‌‌‍‍‍‌‌‍⁠⁠‌​‌‍⁠‍​⁠‌​⁠‌⁠⁠​⁣ --- 1. 顶部栏 --- */
.top-row {
  display: flex; justify-content: space-between; align-items: flex-start;
}
.album-cover {
  width: 72px; height: 72px; 
  border-radius: 22px; 
  overflow: hidden;
  background-color: transparent;
  box-shadow: 0 6px 14px rgba(0,0,0,0.04); 
  margin-left: 6px; 
}
.album-cover img {
  width: 100%; height: 100%; object-fit: cover; display: block;
}

.cover-placeholder {
  width: 100%; height: 100%; 
  position: relative;
  display: none; align-items: center; justify-content: center;
  color: var(--icon-color);
  z-index: 1;
}
.cover-placeholder::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background-color: var(--placeholder-bg-color);
  backdrop-filter: blur(20px) brightness(1.1) saturate(120%);
  -webkit-backdrop-filter: blur(20px) brightness(1.1) saturate(120%);
  z-index: -1;
}
.cover-placeholder svg { 
  width: 32px; height: 32px; 
  opacity: 0.9;
}

.cast-btn {
  width: 46px; height: 46px;
  display: flex; align-items: center; justify-content: center;
  color: var(--cast-icon-color);
  margin-top: 4px; 
  position: relative;
  z-index: 1;
}
.cast-btn::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  border-radius: 50%;
  background-color: var(--cast-bg-color);
  backdrop-filter: blur(25px) brightness(1.06) saturate(120%);
  -webkit-backdrop-filter: blur(25px) brightness(1.06) saturate(120%);
  box-shadow: 
    inset 0 1px 0px rgba(255, 255, 255, 0.2),
    inset 0 0 0 1px rgba(255, 255, 255, 0.08);
  z-index: -1;
}
.cast-btn svg { 
  width: 26px; height: 26px; 
}

/* 🌟 === 中等/小尺寸适配 === 🌟 */
.mz-music-widget.size-medium .album-cover { width: 67px; height: 67px; border-radius: 20px; }
.mz-music-widget.size-medium .cover-placeholder svg { width: 30px; height: 30px; }
.mz-music-widget.size-medium .cast-btn { width: 42px; height: 42px; }
.mz-music-widget.size-medium .cast-btn svg { width: 24px; height: 24px; }

.mz-music-widget.size-small .album-cover { width: 62px; height: 62px; border-radius: 18px; }
.mz-music-widget.size-small .cover-placeholder svg { width: 28px; height: 28px; }
.mz-music-widget.size-small .cast-btn { width: 38px; height: 38px; }
.mz-music-widget.size-small .cast-btn svg { width: 22px; height: 22px; }

/* --- 2. 文本信息区 --- */
.text-row {
  display: flex; flex-direction: column; 
  gap: 0px; 
  margin-top: auto; 
  margin-bottom: 12px; 
  align-items: flex-start; 
  margin-left: 6px; 
}
.song-title {
  color: var(--song-color); font-size: var(--song-size); 
  font-weight: 500; 
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  max-width: 100%; 
  line-height: 1.15; 
}
.artist-name {
  color: var(--artist-color); font-size: var(--artist-size); 
  font-weight: 400;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  max-width: 100%;
  line-height: 1.15;
}

/* --- 3. 底部播放控制区 --- */
.controls-row {
  display: flex; justify-content: center; align-items: center; 
  gap: 8px; 
  margin-bottom: -4px; 
}
.ctrl-icon {
  color: var(--icon-color);
  display: flex; align-items: center; justify-content: center;
}

/* 🌟 去除了 prev-next 的独立透明度和混合模式，彻底与 play-btn 保持一致纯色 */

.play-btn svg { width: 36px; height: 30px; }
.prev-next svg { width: 52px; height: 30px; }

value.css:
/*⁣‌⁠‌‍‌‌​‌‍‌‌‌‌⁠‍⁠⁠⁠​⁠​‌⁠⁠​⁠⁠‍‍‌​‌⁠​​​‌‍⁠‌‌‍‍‍‌‌‍⁠⁠‌​‌‍⁠‍​⁠‌​⁠‌⁠⁠​⁣ ios6消息列表·粉by白咪饭 — nuojiji messaging app theme */

/* QQ_消息列表 古早iOS6拟物复刻版·奶白粉 by白咪饭 */

:root {
    --nj-msg-chat-bg: #fffdfe; 
    --nj-msg-bg: #fffdfe;
    --nj-msg-text: #000000;
    --nj-msg-text-muted: #b3aab0;
    --nj-msg-text-time: #c8c2c6;
    --nj-msg-unread-bg: #ff3b30; 
    --nj-msg-card-bg-pinned: #fff5f7; 
    --nj-msg-avatar-radius: 50%; 
    --nj-msg-tabbar-bg: #fdf7f9;
    --nj-msg-tabbar-active: #d3aebb;
    --nj-msg-tabbar-inactive: #b3aab0;
    --nj-msg-tabbar-border: 1px solid #f7ecf0;
}

/* 🌟 核心防抖修复 + iOS6经典拉丝底纹 🌟 */
#messaging-chat-tab {
    overflow-x: hidden !important;
    width: 100% !important;
    max-width: 100vw !important;
    background-color: #fff8fa !important;
    background-image: 
        repeating-linear-gradient(90deg, rgba(255,255,255,0.5) 0px, rgba(255,255,255,0.5) 1px, transparent 1px, transparent 3px),
        linear-gradient(180deg, rgba(255,255,255,0.6), rgba(255,255,255,0) 40%) !important;
}

/* ==========================================
   1. 顶栏复刻 (iOS6玻璃光泽渐变 - 柔和无截断)
========================================== */
.nj-chat-tab-header {
    /* 🌟 奶白粉果冻光泽，浅到近乎白色 🌟 */
    background: 
        linear-gradient(180deg, 
            rgba(255,255,255,0.7) 0%, 
            rgba(255,255,255,0.45) 18%, 
            rgba(255,255,255,0.25) 34%, 
            rgba(255,255,255,0.1) 48%, 
            rgba(255,255,255,0) 60%, 
            rgba(0,0,0,0.01) 80%, 
            rgba(0,0,0,0.02) 100%),
        linear-gradient(180deg, #fdf3f6 0%, #faeef2 45%, #f7e9ee 72%, #f4e5eb 100%) !important; 
    border-bottom: 1px solid #eedbe2 !important;
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.9), 0 1px 3px rgba(180,160,170,0.1) !important;
    height: calc(50px + var(--nuo-safe-top)) !important;
    padding: 0 !important;
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    z-index: 9999 !important;
}

.nj-chat-tab-header::before, .nj-chat-tab-header::after {
    display: none !important;
    content: '' !important;
}

/* 🐧 左侧头像 (无边框无阴影) 🐧 */
.nj-chat-tab-header-back svg { display: none !important; } 
.nj-chat-tab-header-back {
    display: block !important; 
    position: absolute !important;
    width: 40px !important; 
    height: 40px !important; 
    left: 14px !important; 
    top: calc(0px + var(--nuo-safe-top)) !important; 
    z-index: 99 !important; 
    border-radius: 50% !important;
    overflow: hidden !important;
    border: none !important;
    box-shadow: none !important;
    background-image: url('https://i.postimg.cc/yYTV3tV0/IMG-4796.jpg') !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
}
.nj-chat-tab-header-back::after { content: ''; }

/* 👤 昵称 + 状态 👤 */
.nj-chat-tab-header-title-btn {
    display: flex !important;
    position: absolute !important;
    left: 64px !important; 
    transform: none !important;
    top: calc(0px + var(--nuo-safe-top)) !important; 
    align-items: flex-start !important;
    justify-content: center !important; 
    flex-direction: column !important;
    color: transparent !important; 
    background: transparent !important;
    z-index: 100 !important;
    height: auto !important;
    padding: 0 !important;
}
.nj-chat-tab-header-title-btn svg { display: none !important; }

.nj-chat-tab-header-title-btn::before {
    display: block !important;
    content: 'nix' !important;
    font-size: 17px !important; 
    font-weight: 700 !important;
    color: #7a6a70 !important; 
    text-shadow: 0 1px 0 rgba(255,255,255,0.85) !important;
    line-height: 1.3 !important;
}

/* 🟢 4G在线状态 (可单独调整上下位置) 🟢 */
.nj-chat-tab-header-title-btn::after {
    display: block !important;
    content: '5G在线  ›' !important;
    font-size: 12px !important; 
    font-weight: 400 !important;
    color: #aa9aa0 !important; 
    text-shadow: 0 1px 0 rgba(255,255,255,0.6) !important;
    line-height: 1.4 !important;
    padding-left: 14px !important;
    background-image: radial-gradient(circle, #34c759 45%, transparent 46%) !important;
    background-size: 10px 10px !important;
    background-repeat: no-repeat !important;
    background-position: left center !important;
    /* 👇👇 4G状态的上下位置在这里单独调：正数往下，负数往上 👇👇 */
    position: relative !important;
    top: -32px !important;
}

/* ➕ 右侧加号 (浅粉灰浮雕) ➕ */
.nj-chat-tab-header-edit svg { display: none !important; }
.nj-chat-tab-header-edit {
    background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%237a6a70" stroke-width="1.6"><line x1="12" y1="4" x2="12" y2="20"/><line x1="4" y1="12" x2="20" y2="12"/></svg>');
    background-size: 26px;
    background-repeat: no-repeat;
    background-position: center;
    width: 32px !important;
    height: 32px !important;
    position: absolute;
    right: 16px;
    top: calc(3px + var(--nuo-safe-top));
    filter: drop-shadow(0 1px 0 rgba(255,255,255,0.7)) !important;
}

/* ==========================================
   2. 搜索框 (iOS6奶白粉底 + 圆角内凹胶囊)
========================================== */
.nj-chat-tab-search-wrap {
    display: block !important;
    background: 
        linear-gradient(180deg, rgba(255,255,255,0.5), rgba(255,255,255,0) 60%),
        linear-gradient(180deg, #fbf1f4, #f8ecf0) !important; 
    padding: 12px 12px 12px 12px !important;
    margin: 0 !important;
    margin-top: calc(50px + var(--nuo-safe-top)) !important;
    position: relative !important;
    box-sizing: border-box !important;
    width: 100% !important;
    border-bottom: 1px solid #f0dee5 !important;
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.6) !important;
}

.nj-chat-tab-search {
    background: 
        linear-gradient(180deg, rgba(0,0,0,0.025), rgba(0,0,0,0) 30%),
        #ffffff !important;
    border-radius: 22px !important; 
    height: 33px !important; 
    border: 1px solid #f0dce4 !important;
    box-shadow: inset 0 2px 3px rgba(180,160,170,0.08) !important;
    position: relative !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    width: 100% !important;
    box-sizing: border-box !important;
    overflow: hidden !important;
}

.nj-chat-tab-search * {
    display: none !important;
}

/* 🔍 SVG搜索图标 + 文字 (居中) */
.nj-chat-tab-search::before {
    content: '搜索' !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    font-size: 15px !important;
    color: #c2b2b8 !important;
    text-align: center !important;
    padding-left: 24px !important;
    background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23c2b2b8" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="7"/><line x1="21" y1="21" x2="16.5" y2="16.5"/></svg>') !important;
    background-size: 17px 17px !important;
    background-repeat: no-repeat !important;
    background-position: left center !important;
}

/* 隐藏无关区 */
.nj-chat-tab-decor-top,
.nj-chat-tab-decor-mid,
.nj-chat-tab-decor-bottom,
.nj-chat-tab-notes,
.nj-chat-tab-section-title {
    display: none !important;
}

/* ==========================================
   3. 聊天列表项 (纯色无渐变 + iOS6双线分割)
========================================== */
.nj-chat-tab-list {
    padding-top: 0px !important;
    background: #fffdfe !important; 
}
.nj-chat-item {
    padding: 12px 16px !important; 
    border-bottom: 1px solid #f7ecf0 !important;
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.95) !important;
    margin: 0 !important;
    background: #ffffff !important;
    position: relative;
}
.nj-chat-item:active {
    background: #fdf3f6 !important;
}

/* 🐧 列表头像 (无边框无阴影) 🐧 */
.nj-chat-item-avatar {
    width: 48px !important;  
    height: 48px !important;
    border-radius: 50% !important; 
    margin-right: 12px !important; 
    border: none !important;
    box-shadow: none !important;
}
.nj-chat-item-name {
    font-size: 16px !important;
    color: #6a5a60 !important;
    font-weight: 600 !important;
    text-shadow: 0 1px 0 rgba(255,255,255,0.95) !important;
