    color: var(--nj-msg-text-muted) !important; 
}
.nj-chat-item-time {
    font-size: 12px !important;
    color: var(--nj-msg-text-time) !important;
}

/* 隐藏大头钉 */
.nj-chat-item-pin-mark { display: none !important; }
.nj-chat-item-pinned { background: #fff5f7 !important; }

/* ==========================================
   4. 底栏重绘 (iOS6金属果冻光泽 + 线描图标)
========================================== */
.nj-tab-bottom-bar {
    background: 
        linear-gradient(180deg, rgba(255,255,255,0.6) 0%, rgba(255,255,255,0.25) 30%, rgba(255,255,255,0) 55%, rgba(0,0,0,0.01) 100%),
        linear-gradient(180deg, #fbf1f4 0%, #f8ecf0 55%, #f5e8ed 100%) !important;
    border-top: 1px solid #eedbe2 !important;
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.8) !important;
}
.nj-tab-bottom-icon svg { display: none !important; }
.nj-tab-bottom-item {
    display: flex !important;
    flex-direction: column !important;
    justify-content: center !important;
    align-items: center !important;
    gap: 3px !important;
}
.nj-tab-bottom-item::after {
    font-size: 11px !important;
    color: #aa9aa0;
    text-shadow: 0 1px 0 rgba(255,255,255,0.7) !important;
}
.nj-tab-bottom-item-active::after {
    color: #d3aebb !important;
}
.nj-tab-bottom-item-chat::after { content: '消息'; }
.nj-tab-bottom-item-moments::after { content: '频道'; }
.nj-tab-bottom-item-favorites::after { content: '联系人'; }
.nj-tab-bottom-item-profile::after { content: '动态'; }

.nj-tab-bottom-icon {
    width: 26px !important;
    height: 26px !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
}

/* 消息-空心气泡线描图标 (激活浅粉) */
.nj-tab-bottom-item-chat .nj-tab-bottom-icon {
    background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23c2b2b8" stroke-width="1.6"><path d="M12 3C6.5 3 2 6.6 2 11c0 2.4 1.3 4.6 3.4 6.1L4.5 21l3.8-2c1.1.3 2.4.5 3.7.5 5.5 0 10-3.6 10-8s-4.5-8-10-8z"/></svg>');
